#!/usr/bin/env python3
"""Orchestrate Gate 1/2/3/6 live experiments in one long-lived process."""

from __future__ import annotations

# --- github publish layout (auto-generated by sync_github_publish.py) ---
import sys
from pathlib import Path as _Path
_GITHUB_ROOT = _Path(__file__).resolve().parents[1]
_BG = _GITHUB_ROOT / "BoundaryGuard"
_EXP = _GITHUB_ROOT / "exp"
for _p in (_BG, _EXP):
    _s = str(_p)
    if _s not in sys.path:
        sys.path.insert(0, _s)
DATA = _GITHUB_ROOT.joinpath("data")
EXP = _EXP
ROOT = _GITHUB_ROOT
# --- end header ---

import json
import subprocess
import sys
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path


ROOT = _GITHUB_ROOT
WORK = ROOT / "work"
LOGS = WORK / "logs"
LOGS.mkdir(parents=True, exist_ok=True)


def run(name: str, args: list[str]) -> dict:
    log = LOGS / f"{name}.log"
    print(f"START {name}", flush=True)
    started = time.time()
    with log.open("w") as handle:
        proc = subprocess.run(
            [sys.executable, *args],
            cwd=str(ROOT),
            stdout=handle,
            stderr=subprocess.STDOUT,
        )
    elapsed = time.time() - started
    result = {"name": name, "returncode": proc.returncode, "elapsed_s": elapsed, "log": str(log)}
    print(f"DONE {name} rc={proc.returncode} elapsed={elapsed:.1f}s", flush=True)
    return result


def main() -> None:
    jobs = [
        ("gate1_scale", ["work/scale_four_chain_1000.py"]),
        ("gate2_natural", ["work/natural_fault_multiday.py", "--per-chain", "8"]),
        ("gate6_frontier", ["work/frontier_multiday.py", "--per-chain", "24"]),
        ("gate3_relayer", ["work/relayer_proxy_live.py", "--limit", "60", "--port", "18545"]),
    ]
    results = []
    # Gate3 uses a local port; keep it sequential with others that hammer public RPCs
    # by running all in parallel carefully: 1,2,6 parallel then 3, or all parallel with distinct load.
    with ThreadPoolExecutor(max_workers=4) as pool:
        futures = {pool.submit(run, name, args): name for name, args in jobs}
        for future in as_completed(futures):
            results.append(future.result())
    out = WORK / "data" / "live_strong_gates_run.json"
    out.write_text(json.dumps({"results": results, "finished_at": time.time()}, indent=2) + "\n")
    print(json.dumps(results, indent=2), flush=True)
    if any(row["returncode"] != 0 for row in results):
        sys.exit(1)


if __name__ == "__main__":
    main()
